def container_titles_to_venues(apps, schema_editor):
    Publication = apps.get_model('base', 'Publication')
    Venue = apps.get_model('base', 'Venue')
    database = schema_editor.connection.alias
    venues = {}
    publications = Publication.objects.using(database).exclude(container_title='').iterator()
    for publication in publications:
        name = publication.container_title.strip()
        if not name:
            continue
        venue = venues.get(name)
        if venue is None:
            venue, _ = Venue.objects.using(database).get_or_create(name=name)
            venues[name] = venue
        publication.venue_id = venue.pk
        publication.save(using=database, update_fields=('venue',))


def venues_to_container_titles(apps, schema_editor):
    Publication = apps.get_model('base', 'Publication')
    database = schema_editor.connection.alias
    publications = Publication.objects.using(database).filter(venue__isnull=False).select_related('venue')
    for publication in publications.iterator():
        publication.container_title = publication.venue.name
        publication.save(using=database, update_fields=('container_title',))


